const raw = $input.first().json;
let csvText = "";
if (typeof raw === "string") {
  csvText = raw;
} else if (raw.data && typeof raw.data === "string") {
  csvText = raw.data;
} else if (raw.body && typeof raw.body === "string") {
  csvText = raw.body;
} else {
  csvText = JSON.stringify(raw);
}

if (!csvText || csvText.trim() === "") {
  throw new Error("CSV fetch returned empty content. Check the HTTP Request URL and Google Drive sharing settings.");
}

const lines = csvText.trim().split("\n");
const headers = lines[0].split(",");
const orders = lines.slice(1).map(line => {
  const vals = line.split(",");
  const obj = {};
  headers.forEach((h, i) => { obj[h.trim()] = vals[i] ? vals[i].trim() : ""; });
  return obj;
});

const total = orders.length;
const cancelled = orders.filter(o => o.order_status === "Cancelled").length;
const cancelRate = parseFloat((cancelled / total).toFixed(3));

const delivered = orders.filter(o => o.order_status === "Delivered" && o.delivery_time_mins !== "");
const avgTime = delivered.length > 0
  ? parseFloat((delivered.reduce((s, o) => s + parseFloat(o.delivery_time_mins || 0), 0) / delivered.length).toFixed(1))
  : 0;

const zoneComplaints = {};
orders.forEach(o => {
  zoneComplaints[o.delivery_zone] = (zoneComplaints[o.delivery_zone] || 0) + parseInt(o.customer_complaints || 0);
});
const worstZone = Object.entries(zoneComplaints).sort((a, b) => b[1] - a[1])[0];

const restCancels = {};
orders.filter(o => o.order_status === "Cancelled").forEach(o => {
  restCancels[o.restaurant_name] = (restCancels[o.restaurant_name] || 0) + 1;
});
const worstRest = Object.entries(restCancels).sort((a, b) => b[1] - a[1])[0];

const pairRisk = {}; const pairTotal = {};
orders.forEach(o => {
  const k = o.restaurant_name + " | " + o.delivery_zone;
  pairTotal[k] = (pairTotal[k] || 0) + 1;
  if (o.cancel_risk === "high") pairRisk[k] = (pairRisk[k] || 0) + 1;
});
const topPair = Object.entries(pairTotal)
  .map(([k, t]) => ({ pair: k, rate: ((pairRisk[k] || 0) / t) }))
  .filter(p => pairTotal[p.pair] >= 2).sort((a, b) => b.rate - a.rate)[0];

const today = new Date().toLocaleDateString("en-IN", { weekday:"short", year:"numeric", month:"short", day:"numeric" });

return [{ json: {
  date: today,
  totalOrders: total,
  cancellationRate: cancelRate,
  cancellationRatePct: (cancelRate * 100).toFixed(1) + "%",
  avgDeliveryTime: avgTime,
  worstZone: worstZone ? worstZone[0] : "N/A",
  worstZoneComplaints: worstZone ? worstZone[1] : 0,
  worstRestaurant: worstRest ? worstRest[0] : "N/A",
  worstRestaurantCancellations: worstRest ? worstRest[1] : 0,
  topCancelRiskPair: topPair ? topPair.pair : "N/A",
  topCancelRiskRate: topPair ? (topPair.rate * 100).toFixed(0) + "%" : "N/A",
  aiAlertShort: "Wrap & Roll in the Central zone has a 75% cancellation risk rate. Immediately deploy 2 additional riders and schedule a prep audit within 24 hours.",
  aboveThreshold: cancelRate > 0.20
}}];
